// Load the cached tool catalog so the LLM knows every pipeline's knobs+stages.
const fs = require('fs');
const catalogPath = $env.CESAROPS_CATALOG || '/home/cesarops/wreckhunter2000-1/n8n/tool_catalog.json';
let catalog = {};
try { catalog = JSON.parse(fs.readFileSync(catalogPath, 'utf8')); } catch (e) {}
const body = items[0].json.body || items[0].json;
return [{ json: { query: body.query || '', dry_run: !!body.dry_run, catalog } }];

