// Extract the JSON plan from the LLM response; carry dry_run through.
const resp = items[0].json;
let content = '';
try { content = resp.choices[0].message.content; } catch (e) { content = ''; }
let plan = { plan: [] };
const m = content.match(/\{[\s\S]*\}/);
if (m) { try { plan = JSON.parse(m[0]); } catch (e) {} }
// Attach dry_run from the original webhook (kept on the items meta if present).
const dry = $('Load Tool Catalog').first().json.dry_run;
for (const step of (plan.plan || [])) {
  step.inputs = step.inputs || {};
  if (dry) { step.inputs.dry_run = true; }
}
return (plan.plan || []).map(step => ({ json: step }));

// Route each plan step to its specialist webhook. Returns the URL + payload.
const base = $env.N8N_WEBHOOK_BASE || 'http://127.0.0.1:5678/webhook';
const step = items[0].json;
const map = {
  satellite: 'specialist-satellite',
  aeromag: 'specialist-aeromag', aeromagnetic: 'specialist-aeromag', mag: 'specialist-aeromag',
  bag: 'specialist-bag'
};
const path = map[step.pipeline];
if (!path) { return [{ json: { error: 'unknown pipeline in plan', step } }]; }
const payload = Object.assign({}, step.inputs, { knobs: step.knobs, stages: step.stages });
return [{ json: { url: `${base}/${path}`, payload, pipeline: step.pipeline, reason: step.reason } }];
